param()

$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host " HOGWARTS - MOBILE V3 UI + TOUCH REPAIR" -ForegroundColor Yellow
Write-Host " Screenshot-driven layout repair" -ForegroundColor Gray
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host ""

$root = Get-Location

foreach ($file in @("index.html","product\product-v2.css","product\client-product-v2.js")) {
    if (!(Test-Path $file)) {
        throw "Execute na raiz C:\hogwarts com Product V2 aplicado. Faltou: $file"
    }
}

if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    throw "Node.js nao encontrado no PATH."
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $root ".hogwarts-mobile-v3-backup-$stamp"
New-Item -ItemType Directory -Path (Join-Path $backup "product") -Force | Out-Null

Copy-Item "index.html" (Join-Path $backup "index.html") -Force

foreach ($file in @(
    "product\mobile-product-v2.css",
    "product\mobile-product-v2.js",
    "product\mobile-product-v3.css",
    "product\mobile-product-v3.js"
)) {
    if (Test-Path $file) {
        Copy-Item $file (Join-Path $backup $file) -Force
    }
}

Write-Host "[1/4] Backup criado: $backup" -ForegroundColor Cyan

$patcherPath = Join-Path $root ".mobile-v3-patcher.js"
[IO.File]::WriteAllBytes(
    $patcherPath,
    [Convert]::FromBase64String("")
)

try {
    Write-Host "[2/4] Substituindo camada mobile anterior..." -ForegroundColor Cyan
    node $patcherPath
    if ($LASTEXITCODE -ne 0) { throw "Falha no transformador Mobile V3." }

    Write-Host "[3/4] Validando touch/runtime..." -ForegroundColor Cyan
    node --check "product\mobile-product-v3.js"
    if ($LASTEXITCODE -ne 0) { throw "Erro de sintaxe no Mobile V3 JS." }

    Write-Host "[4/4] Validando links e protecoes..." -ForegroundColor Cyan
    $html = Get-Content "index.html" -Raw
    $css = Get-Content "product\mobile-product-v3.css" -Raw
    $js = Get-Content "product\mobile-product-v3.js" -Raw

    if ($html -notmatch "mobile-product-v3.css") { throw "CSS Mobile V3 nao vinculado." }
    if ($html -notmatch "mobile-product-v3.js") { throw "JS Mobile V3 nao vinculado." }
    if ($html -match "mobile-product-v2.js") { throw "JS Mobile V2 antigo ainda esta carregado." }
    if ($css -notmatch "\.container") { throw "Correcao de espaco superior ausente." }
    if ($css -notmatch "hud-gamificacao-topo") { throw "Correcao do painel Diario ausente." }
    if ($js -notmatch "bindCastleJoystick") { throw "Controle touch do castelo ausente." }

    $rollback = @"
param()
`$ErrorActionPreference = "Stop"
`$root = Split-Path -Parent `$MyInvocation.MyCommand.Path
`$backup = "$backup"
if (!(Test-Path `$backup)) { throw "Backup nao encontrado: `$backup" }

Copy-Item (Join-Path `$backup "index.html") (Join-Path `$root "index.html") -Force

foreach (`$file in @(
    "product\mobile-product-v2.css",
    "product\mobile-product-v2.js",
    "product\mobile-product-v3.css",
    "product\mobile-product-v3.js"
)) {
    `$src = Join-Path `$backup `$file
    `$dst = Join-Path `$root `$file
    if (Test-Path `$src) {
        Copy-Item `$src `$dst -Force
    } elseif (Test-Path `$dst) {
        Remove-Item `$dst -Force
    }
}

Write-Host "Rollback Mobile V3 concluido." -ForegroundColor Yellow
"@

    [IO.File]::WriteAllText(
        (Join-Path $root "ROLLBACK_HOGWARTS_MOBILE_V3.ps1"),
        $rollback,
        (New-Object Text.UTF8Encoding($false))
    )

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " MOBILE V3 INSTALADO" -ForegroundColor Green
    Write-Host " Touch + encaixe + header + diario corrigidos" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "No telefone, feche a aba e abra novamente para limpar o CSS antigo." -ForegroundColor White
}
finally {
    if (Test-Path $patcherPath) {
        Remove-Item $patcherPath -Force -ErrorAction SilentlyContinue
    }
}
